;/**
 * Pure JavaScript SmartMenu Implementation
 * Replicates SmartMenus jQuery functionality
 */

(function() {
    'use strict';

    function SmartMenu(menuId) {
        this.menu = document.getElementById(menuId);
        if (!this.menu) return;

        this.init();
    }

    SmartMenu.prototype.init = function() {
        var self = this;
        var menuItems = this.menu.querySelectorAll('li');

        // Add classes and setup
        Array.prototype.forEach.call(menuItems, function(item) {
            var submenu = item.querySelector('ul');
            
            if (submenu) {
                item.classList.add('has-submenu');
                submenu.classList.add('sub-menu');
                
                // Add arrow element to the link
                var link = item.querySelector('a');
                var arrow = null;
                if (link) {
                    // Check if arrow already exists
                    var existingArrow = link.querySelector('.sub-arrow');
                    if (!existingArrow) {
                        arrow = document.createElement('span');
                        arrow.className = 'sub-arrow';
                        link.appendChild(arrow);
                    } else {
                        arrow = existingArrow;
                    }
                }
                
                // Handle hover (desktop)
                item.addEventListener('mouseenter', function(e) {
                    if (window.innerWidth > 768) {
                        self.showSubmenu(item, submenu);
                    }
                });
                
                item.addEventListener('mouseleave', function(e) {
                    if (window.innerWidth > 768) {
                        self.hideSubmenu(item, submenu);
                    }
                });

                // Handle click on arrow (mobile and desktop)
                if (arrow) {
                    arrow.addEventListener('click', function(e) {
                        e.preventDefault();
                        e.stopPropagation();
                        self.toggleSubmenu(item, submenu);
                    });
                }

                // Handle click on link (mobile only - to prevent navigation)
                if (link) {
                    link.addEventListener('click', function(e) {
                        // If clicking on the arrow, let arrow handler take care of it
                        if (e.target.classList.contains('sub-arrow') || e.target.closest('.sub-arrow')) {
                            return;
                        }
                        // On mobile, prevent navigation if there's a submenu
                        if (window.innerWidth <= 768 && submenu) {
                            e.preventDefault();
                            self.toggleSubmenu(item, submenu);
                        }
                    });
                }
            }
        });

        // Close submenus when clicking outside
        document.addEventListener('click', function(e) {
            if (!self.menu.contains(e.target)) {
                self.closeAllSubmenus();
            }
        });

        // Handle window resize
        window.addEventListener('resize', function() {
            self.closeAllSubmenus();
        });
    };

    SmartMenu.prototype.showSubmenu = function(item, submenu) {
        // Close other submenus at the same level
        this.closeSiblingSubmenus(item);
        
        // Show this submenu
        item.classList.add('active');
        submenu.classList.add('active');
        submenu.style.display = 'block';
        
        // Add highlighted class to link for arrow change
        var link = item.querySelector('a');
        if (link) {
            link.classList.add('highlighted');
        }
        
        // Position submenu
        this.positionSubmenu(item, submenu);
    };

    SmartMenu.prototype.hideSubmenu = function(item, submenu) {
        // Only hide if not hovering over submenu
        var self = this;
        setTimeout(function() {
            if (!item.matches(':hover') && !submenu.matches(':hover')) {
                item.classList.remove('active');
                submenu.classList.remove('active');
                submenu.style.display = '';
                
                // Remove highlighted class from link
                var link = item.querySelector('a');
                if (link) {
                    link.classList.remove('highlighted');
                }
            }
        }, 100);
    };

    SmartMenu.prototype.toggleSubmenu = function(item, submenu) {
        var link = item.querySelector('a');
        if (submenu.classList.contains('active')) {
            this.closeSubmenu(item, submenu);
        } else {
            this.closeSiblingSubmenus(item);
            item.classList.add('active');
            submenu.classList.add('active');
            submenu.style.display = 'block';
            if (link) {
                link.classList.add('highlighted');
            }
            this.positionSubmenu(item, submenu);
        }
    };

    SmartMenu.prototype.closeSubmenu = function(item, submenu) {
        item.classList.remove('active');
        submenu.classList.remove('active');
        submenu.style.display = '';
        
        // Remove highlighted class from link
        var link = item.querySelector('a');
        if (link) {
            link.classList.remove('highlighted');
        }
        
        // Close nested submenus
        var nestedSubmenus = submenu.querySelectorAll('.sub-menu');
        var self = this;
        Array.prototype.forEach.call(nestedSubmenus, function(nested) {
            nested.classList.remove('active');
            nested.style.display = '';
            var nestedItem = nested.parentElement;
            nestedItem.classList.remove('active');
            var nestedLink = nestedItem.querySelector('a');
            if (nestedLink) {
                nestedLink.classList.remove('highlighted');
            }
        });
    };

    SmartMenu.prototype.closeSiblingSubmenus = function(item) {
        var parent = item.parentElement;
        if (parent) {
            var siblings = parent.querySelectorAll('li.has-submenu');
            var self = this;
            Array.prototype.forEach.call(siblings, function(sibling) {
                if (sibling !== item) {
                    var siblingSubmenu = sibling.querySelector('.sub-menu');
                    if (siblingSubmenu) {
                        self.closeSubmenu(sibling, siblingSubmenu);
                    }
                }
            });
        }
    };

    SmartMenu.prototype.closeAllSubmenus = function() {
        var self = this;
        var allSubmenus = this.menu.querySelectorAll('.sub-menu');
        Array.prototype.forEach.call(allSubmenus, function(submenu) {
            var item = submenu.parentElement;
            self.closeSubmenu(item, submenu);
        });
    };

    SmartMenu.prototype.positionSubmenu = function(item, submenu) {
        // Reset positioning
        submenu.style.left = '';
        submenu.style.right = '';
        submenu.style.top = '';
        
        // Get positions
        var itemRect = item.getBoundingClientRect();
        var submenuRect = submenu.getBoundingClientRect();
        var viewportWidth = window.innerWidth;
        var viewportHeight = window.innerHeight;
        
        // Check if submenu is a direct child (horizontal positioning)
        var isDirectChild = item.parentElement === this.menu;
        
        if (isDirectChild) {
            // Top-level submenu - position below
            submenu.style.top = itemRect.height + 'px';
            submenu.style.left = '0';
            
            // Check if submenu goes off right edge
            if (itemRect.left + submenuRect.width > viewportWidth) {
                submenu.style.left = 'auto';
                submenu.style.right = '0';
            }
        } else {
            // Nested submenu - position to the right
            submenu.style.top = '0';
            submenu.style.left = itemRect.width + 'px';
            
            // Check if submenu goes off right edge, position to left instead
            if (itemRect.right + submenuRect.width > viewportWidth) {
                submenu.style.left = 'auto';
                submenu.style.right = itemRect.width + 'px';
            }
            
            // Check if submenu goes off bottom edge
            if (itemRect.bottom + submenuRect.height > viewportHeight) {
                submenu.style.top = 'auto';
                submenu.style.bottom = '0';
            }
        }
    };

    // Initialize when DOM is ready
    function initMenu() {
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function() {
                new SmartMenu('main-menu');
            });
        } else {
            new SmartMenu('main-menu');
        }
    }

    initMenu();

})();





;/**
 * Language Switcher Dropdown
 * Opens/closes language list when clicking on current language
 */

(function() {
    'use strict';

    function initLanguageSwitcher() {
        var trigger = document.getElementById('current-lang-trigger');
        var dropdown = document.getElementById('lang-dropdown');
        var arrow = trigger ? trigger.querySelector('.lang-arrow') : null;

        if (!trigger || !dropdown) {
            return;
        }

        // Toggle dropdown on click
        trigger.addEventListener('click', function(e) {
            e.stopPropagation();
            
            var isOpen = dropdown.classList.contains('show');
            
            if (isOpen) {
                dropdown.classList.remove('show');
                if (arrow) {
                    arrow.style.transform = 'rotate(0deg)';
                }
            } else {
                dropdown.classList.add('show');
                if (arrow) {
                    arrow.style.transform = 'rotate(180deg)';
                }
            }
        });

        // Close dropdown when clicking outside
        document.addEventListener('click', function(e) {
            if (!trigger.contains(e.target) && !dropdown.contains(e.target)) {
                dropdown.classList.remove('show');
                if (arrow) {
                    arrow.style.transform = 'rotate(0deg)';
                }
            }
        });

        // Close dropdown when selecting a language
        var langItems = dropdown.querySelectorAll('.lang-item a');
        Array.prototype.forEach.call(langItems, function(item) {
            item.addEventListener('click', function() {
                dropdown.classList.remove('show');
                if (arrow) {
                    arrow.style.transform = 'rotate(0deg)';
                }
            });
        });
    }

    // Initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initLanguageSwitcher);
    } else {
        initLanguageSwitcher();
    }

})();

// Мобильное меню
(function() {
    'use strict';
    
    function initMobileMenu() {
        var hamburgerBtn = document.querySelector('.hamburger-btn');
        var closeBtn = document.getElementById('mobile-menu-close');
        var nav = document.getElementById('mobile-nav');
        
        if (!hamburgerBtn || !nav) {
            return;
        }
        
        // Открытие меню по клику на бургер
        hamburgerBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            nav.classList.add('menu-open');
            document.body.style.overflow = 'hidden'; // Блокируем скролл
        });
        
        // Закрытие меню по клику на крестик
        if (closeBtn) {
            closeBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                nav.classList.remove('menu-open');
                document.body.style.overflow = ''; // Разблокируем скролл
            });
        }
        
        // Закрытие меню при клике вне меню
        nav.addEventListener('click', function(e) {
            if (e.target === nav) {
                nav.classList.remove('menu-open');
                document.body.style.overflow = '';
            }
        });
        
        // Закрытие меню при клике на ссылку меню
        var menuLinks = nav.querySelectorAll('#main-menu a');
        Array.prototype.forEach.call(menuLinks, function(link) {
            link.addEventListener('click', function() {
                nav.classList.remove('menu-open');
                document.body.style.overflow = '';
            });
        });
    }
    
    // Инициализация при загрузке DOM
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initMobileMenu);
    } else {
        initMobileMenu();
    }
})();


// Карусель carousel_m
jQuery(document).ready(function($) {
	var currentSlide_m = 0;

	function left_carusel_m(carusel_m, skipUpdate_m){
	   var block_width_m = $(carusel_m).find('.carousel-block_m').outerWidth();
	   $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(-1).clone().prependTo($(carusel_m).find(".carousel-items_m")); 
	   $(carusel_m).find(".carousel-items_m").css({"left":"-"+block_width_m+"px"});
	   $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(-1).remove();    
	   $(carusel_m).find(".carousel-items_m").animate({left: "0px"}, 200); 
	   
	   // Обновление активной точки
	   if(!skipUpdate_m){
	      var totalBlocks_m = $(carusel_m).find('.carousel-block_m').length;
	      currentSlide_m = (currentSlide_m - 1 + totalBlocks_m) % totalBlocks_m;
	      updateDots_m(carusel_m);
	   }
	}
	
	function right_carusel_m(carusel_m, skipUpdate_m){
	   var block_width_m = $(carusel_m).find('.carousel-block_m').outerWidth();
	   $(carusel_m).find(".carousel-items_m").animate({left: "-"+ block_width_m +"px"}, 200, function(){
		  $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(0).clone().appendTo($(carusel_m).find(".carousel-items_m")); 
	      $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(0).remove(); 
	      $(carusel_m).find(".carousel-items_m").css({"left":"0px"}); 
	   }); 
	   
	   // Обновление активной точки
	   if(!skipUpdate_m){
	      var totalBlocks_m = $(carusel_m).find('.carousel-block_m').length;
	      currentSlide_m = (currentSlide_m + 1) % totalBlocks_m;
	      updateDots_m(carusel_m);
	   }
	}

	// Функция для перехода к конкретному слайду
	function goToSlide_m(carusel_m, slideIndex_m){
	   var currentIndex_m = currentSlide_m;
	   var targetIndex_m = slideIndex_m;
	   var diff_m = targetIndex_m - currentIndex_m;
	   var totalBlocks_m = $(carusel_m).find('.carousel-block_m').length;
	   
	   if(diff_m === 0) return;
	   
	   // Вычисляем кратчайший путь (учитывая цикличность)
	   if(Math.abs(diff_m) > totalBlocks_m / 2){
	      diff_m = diff_m > 0 ? diff_m - totalBlocks_m : diff_m + totalBlocks_m;
	   }
	   
	   // Обновляем индекс
	   currentSlide_m = targetIndex_m;
	   updateDots_m(carusel_m);
	   
	   // Рекурсивная функция для последовательного выполнения анимаций
	   function animateStep_m(remaining_m){
	      if(remaining_m === 0) return;
	      
	      if(remaining_m > 0){
	         var block_width_m = $(carusel_m).find('.carousel-block_m').outerWidth();
	         $(carusel_m).find(".carousel-items_m").animate({left: "-"+ block_width_m +"px"}, 200, function(){
	            $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(0).clone().appendTo($(carusel_m).find(".carousel-items_m")); 
	            $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(0).remove(); 
	            $(carusel_m).find(".carousel-items_m").css({"left":"0px"});
	            animateStep_m(remaining_m - 1);
	         });
	      } else {
	         var block_width_m = $(carusel_m).find('.carousel-block_m').outerWidth();
	         $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(-1).clone().prependTo($(carusel_m).find(".carousel-items_m")); 
	         $(carusel_m).find(".carousel-items_m").css({"left":"-"+block_width_m+"px"});
	         $(carusel_m).find(".carousel-items_m .carousel-block_m").eq(-1).remove();    
	         $(carusel_m).find(".carousel-items_m").animate({left: "0px"}, 200, function(){
	            animateStep_m(remaining_m + 1);
	         });
	      }
	   }
	   
	   animateStep_m(diff_m);
	}

	// Функция обновления активной точки
	function updateDots_m(carusel_m){
	   $(carusel_m).find('.carousel-dot_m').removeClass('active_m');
	   $(carusel_m).find('.carousel-dot_m').eq(currentSlide_m).addClass('active_m');
	}

	// Инициализация точек
	function initDots_m(carusel_m){
	   var totalBlocks_m = $(carusel_m).find('.carousel-block_m').length;
	   var dotsContainer_m = $(carusel_m).find('.carousel-dots_m');
	   dotsContainer_m.empty();
	   
	   for(var i_m = 0; i_m < totalBlocks_m; i_m++){
	      var dot_m = $('<span class="carousel-dot_m" data-slide="' + i_m + '"></span>');
	      dotsContainer_m.append(dot_m);
	   }
	   
	   // Обработка клика на точку
	   $(carusel_m).find('.carousel-dot_m').on('click', function(){
	      var slideIndex_m = $(this).data('slide');
	      goToSlide_m(carusel_m, slideIndex_m);
	   });
	   
	   // Устанавливаем первую точку как активную
	   updateDots_m(carusel_m);
	}

	// Автоматическая прокрутка
	function auto_right_m(carusel_m){
		setInterval(function(){
			if (!$(carusel_m).is('.hover'))
				right_carusel_m(carusel_m);
		}, 1000)
	}

	//Обработка клика на стрелку вправо
	$(document).on('click', ".carousel-button-right_m",function(){ 
		var carusel_m = $(this).parents('.carousel_m');
		right_carusel_m(carusel_m);
		return false;
	});
	
	//Обработка клика на стрелку влево
	$(document).on('click',".carousel-button-left_m",function(){ 
		var carusel_m = $(this).parents('.carousel_m');
		left_carusel_m(carusel_m);
		return false;
	});

	// Навели курсор на карусель
	$(document).on('mouseenter', '.carousel_m', function(){$(this).addClass('hover')});
	//Убрали курсор с карусели
	$(document).on('mouseleave', '.carousel_m', function(){$(this).removeClass('hover')});

	//Раскомментируйте строку ниже, чтобы включить автоматическую прокрутку карусели
	// auto_right_m('.carousel_m:first');
	
	// Инициализация точек для всех каруселей
	$('.carousel_m').each(function(){
		initDots_m($(this));
	});
});
;jQuery(document).ready(function($) {
    
    // 1. СНАЧАЛА ОБЪЯВЛЯЕМ ФУНКЦИИ
    function left_carusel(carusel) {
        var block_width = $(carusel).find('.carousel-block').outerWidth();
        $(carusel).find(".carousel-items .carousel-block").eq(-1).clone().prependTo($(carusel).find(".carousel-items")); 
        $(carusel).find(".carousel-items").css({"left":"-"+block_width+"px"});
        $(carusel).find(".carousel-items .carousel-block").eq(-1).remove();    
        $(carusel).find(".carousel-items").animate({left: "0px"}, 200); 
    }

    function right_carusel(carusel) {
        var block_width = $(carusel).find('.carousel-block').outerWidth();
        $(carusel).find(".carousel-items").animate({left: "-"+ block_width +"px"}, 200, function(){
            $(carusel).find(".carousel-items .carousel-block").eq(0).clone().appendTo($(carusel).find(".carousel-items")); 
            $(carusel).find(".carousel-items .carousel-block").eq(0).remove(); 
            $(carusel).find(".carousel-items").css({"left":"0px"}); 
        }); 
    }
/*
    function auto_right(carusel_selector) {
        setInterval(function() {
            var carusel = $(carusel_selector);
            if (!carusel.hasClass('hover')) {
                right_carusel(carusel);
            }
        }, 3000);
    }
*/
    // 2. ЗАТЕМ ВЕШАЕМ СОБЫТИЯ И ЗАПУСКАЕМ
    // Простой и надёжный обработчик кликов по стрелкам
    $(document).on('click', ".carousel-button-right, .carousel-button-right a", function(e) {
        e.preventDefault();
        e.stopPropagation();

        // Запоминаем текущую позицию прокрутки
        var scrollY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;

        // Кнопки находятся вне блока .carousel, поэтому ищем карусель через общий контейнер
        var $carousel = $(this).closest('.region, .container-5, .into-region').find('.carousel').first();

        right_carusel($carousel);

        // Мгновенно возвращаем пользователя в ту же точку
        setTimeout(function() {
            window.scrollTo(0, scrollY);
        }, 0);

        return false;
    });

    $(document).on('click', ".carousel-button-left, .carousel-button-left a", function(e) {
        e.preventDefault();
        e.stopPropagation();

        var scrollY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;

        // Кнопки находятся вне блока .carousel, поэтому ищем карусель через общий контейнер
        var $carousel = $(this).closest('.region, .container-5, .into-region').find('.carousel').first();
        left_carusel($carousel);

        setTimeout(function() {
            window.scrollTo(0, scrollY);
        }, 0);

        return false;
    });

    // Prevent focus on anchor tags (prevents page scroll on first click)
    $('.carousel-button-left a, .carousel-button-right a').attr('tabindex', '-1');
    
    // 3. SWIPE (СВАЙП) ДЛЯ МОБИЛЬНЫХ УСТРОЙСТВ
    var touchStartX = 0;
    var touchStartY = 0;
    var touchEndX = 0;
    var touchEndY = 0;
    var minSwipeDistance = 50; // Минимальное расстояние для свайпа
    
    $(document).on('touchstart', '.carousel-items, .carousel-wrapper', function(e) {
        var touch = e.originalEvent.touches[0];
        touchStartX = touch.clientX;
        touchStartY = touch.clientY;
    });
    
    $(document).on('touchmove', '.carousel-items, .carousel-wrapper', function(e) {
        // Предотвращаем прокрутку страницы при горизонтальном свайпе
        var touch = e.originalEvent.touches[0];
        var deltaX = Math.abs(touch.clientX - touchStartX);
        var deltaY = Math.abs(touch.clientY - touchStartY);
        
        // Если горизонтальное движение больше вертикального, предотвращаем прокрутку
        if (deltaX > deltaY && deltaX > 10) {
            e.preventDefault();
        }
    });
    
    $(document).on('touchend', '.carousel-items, .carousel-wrapper', function(e) {
        var touch = e.originalEvent.changedTouches[0];
        touchEndX = touch.clientX;
        touchEndY = touch.clientY;
        
        var deltaX = touchEndX - touchStartX;
        var deltaY = touchEndY - touchStartY;
        var absDeltaX = Math.abs(deltaX);
        var absDeltaY = Math.abs(deltaY);
        
        // Проверяем, что это горизонтальный свайп (не вертикальный)
        if (absDeltaX > absDeltaY && absDeltaX > minSwipeDistance) {
            e.preventDefault();
            e.stopPropagation();
            
            var $carousel = $(this).closest('.carousel');
            
            // Свайп влево = следующий слайд (right_carusel)
            if (deltaX < 0) {
                right_carusel($carousel);
            }
            // Свайп вправо = предыдущий слайд (left_carusel)
            else if (deltaX > 0) {
                left_carusel($carousel);
            }
        }
    });
    
    // Остановка при наведении
    $(document).on('mouseenter', '.carousel', function(){ $(this).addClass('hover'); });
    $(document).on('mouseleave', '.carousel', function(){ $(this).removeClass('hover'); });

    // Запуск автопрокрутки (закомментировано)
    // auto_right('.carousel:first');
});

